plugins {
    id 'java'
    // bootRun / bootJar 태스크 제공 + 실행 가능한 fat jar 패키징
    id 'org.springframework.boot' version '4.1.1'
    // Boot BOM을 적용해서 아래 의존성들의 버전을 생략할 수 있게 해줌
    id 'io.spring.dependency-management' version '1.1.7'
}

group = 'org.example'
version = '1.0-SNAPSHOT'

java {
    toolchain {
        // 컴파일·실행 JDK를 고정 (Boot 4는 Java 17 이상 필요, 로컬에 설치된 21 사용)
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    compileOnly 'org.projectlombok:lombok'
    annotationProcessor 'org.projectlombok:lombok'
    // Spring MVC + 내장 Tomcat + Jackson (Boot 4부터 starter-web → starter-webmvc로 이름 변경)
    implementation 'org.springframework.boot:spring-boot-starter-webmvc'
    // JPA(Hibernate) + HikariCP 커넥션 풀
    implementation 'org.springframework.boot:spring-boot-starter-data-jpa'
    implementation 'org.mybatis.spring.boot:mybatis-spring-boot-starter:4.1.0'
    // @Valid, @NotBlank 같은 요청 값 검증
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    // MySQL JDBC 드라이버 — 컴파일엔 필요 없고 실행할 때만 필요
    runtimeOnly 'com.mysql:mysql-connector-j'

    // 테스트: JUnit·AssertJ·Mockito·MockMvc 묶음 (버전은 Boot BOM이 관리하므로 junit-bom 따로 두지 않음)
    testImplementation 'org.springframework.boot:spring-boot-starter-webmvc-test'
    // @DataJpaTest(리포지토리만 띄우는 테스트)
    testImplementation 'org.springframework.boot:spring-boot-starter-data-jpa-test'
    // 테스트용 일회용 MySQL 컨테이너 — application-test.yml의 jdbc:tc: URL이 쓴다
    testImplementation 'org.testcontainers:testcontainers-mysql'
    // Gradle이 JUnit Platform 테스트를 실행할 때 필요한 런처
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.named('test') {
    useJUnitPlatform()
    // 테스트는 application-test.yml(Testcontainers MySQL)을 쓰게 한다
    systemProperty 'spring.profiles.active', 'test'
}

package org.example.post;

import org.example.auth.AuthenticatedMember;
import org.example.board.BoardNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

// 글 조회 전용 서비스 — 1-3/1-4의 PostService(쓰기)와 책임을 나눈다
@Service
public class PostQueryService {

    private final PostVisibilityMapper mapper;

    public PostQueryService(PostVisibilityMapper mapper) {
        this.mapper = mapper;
    }


    @Transactional(readOnly = true)
    public List<PostHeadlineResponse> listPublicByAuthor(Long memberId, String boardSlug) {
        if (boardSlug == null || boardSlug.isBlank()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "게시판을 선택해 주세요.");
        }
        if (mapper.findMemberId(memberId) == null) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "회원을 찾을 수 없습니다.");
        }
        if (mapper.findBoardIdBySlug(boardSlug) == null) {
            throw new BoardNotFoundException(boardSlug);
        }
        return mapper.selectPublicByAuthorAndBoard(memberId, boardSlug).stream()
                .map(row -> new PostHeadlineResponse(row.id, row.title,
                        row.authorNickname, row.boardSlug)).toList();
    }

    @Transactional
    public PostDetailResponse getDetail(Long id, AuthenticatedMember viewer) {
        Long viewerId = viewer == null ? null : viewer.id();
        String viewerRole = viewer == null ? null : viewer.role();
        // SQL에서 권한을 먼저 걸러 404일 때 조회수가 변하지 않게 한다.
        PostDetailRow row = mapper.findVisibleDetail(id, viewerId, viewerRole);
        if (row == null) {
            throw new PostNotFoundException();
        }
        mapper.increaseViewCount(id);
        List<String> tags = mapper.findTagsByPostIds(List.of(id)).stream()
                .map(PostTagRow::name).toList();
        return new PostDetailResponse(row.id, row.boardSlug, row.title, row.content,
                tags, row.visibility, new AuthorResponse(row.authorId, row.authorNickname),
                row.viewCount + 1, row.likeCount, row.commentCount, row.createdAt);
    }

    @Transactional(readOnly = true)
    public PostListResponse list(String boardSlug, int page, int size, AuthenticatedMember viewer) {
        Long boardId = mapper.findBoardIdBySlug(boardSlug);
        if (boardId == null) throw new BoardNotFoundException(boardSlug);

        Long viewerId = viewer == null ? null : viewer.id();

        long offset = (long) page * size;
        List<PostListRow> rows = mapper.findViewableByBoard(boardId, viewerId, size, offset);
        long total = mapper.countViewableByBoard(boardId, viewerId);
        Map<Long, List<String>> tags = rows.isEmpty() ? Map.of()
                : mapper.findTagsByPostIds(rows.stream().map(row -> row.id).toList()).stream()
                    .collect(Collectors.groupingBy(PostTagRow::postId,
                            Collectors.mapping(PostTagRow::name, Collectors.toList())));
        List<PostListItemResponse> items = rows.stream()
                .map(row -> toListItem(row, tags.getOrDefault(row.id, List.of()))).toList();

        return new PostListResponse(
                items,
                page,
                size,
                total,
                (int) ((total + size - 1) / size),
                offset + rows.size() < total
        );
    }

    private PostListItemResponse toListItem(PostListRow row, List<String> tags) {
        return new PostListItemResponse(
                row.id,
                row.title,
                new AuthorResponse(row.authorId, row.authorNickname),
                tags,
                row.likeCount,
                row.commentCount,
                row.viewCount,
                row.publishedAt
        );
    }

}

package org.example.post;

import java.time.LocalDateTime;

// 권한 조건을 통과한 상세 SQL 한 행. 태그는 별도 쿼리로 읽는다.
public class PostDetailRow {
    public Long id;
    public String boardSlug;
    public String title;
    public String content;
    public String visibility;
    public Long authorId;
    public String authorNickname;
    public Integer viewCount;
    public Integer likeCount;
    public Integer commentCount;
    public LocalDateTime createdAt;
}

package org.example.post;

import java.time.LocalDateTime;

// 게시판 목록 SQL의 한 행. 태그는 페이지 글 ID로 따로 읽는다.
public class PostListRow {
    public Long id;
    public String title;
    public Long authorId;
    public String authorNickname;
    public Integer likeCount;
    public Integer commentCount;
    public Integer viewCount;
    public LocalDateTime publishedAt;
}

package org.example.post;

public record PostTagRow(Long postId, String name) {
}

package org.example.post;

// 공개 글 목록 SQL이 선택한 네 열만 담는다.
public class PostHeadlineRow {
    public Long id;
    public String title;
    public String authorNickname;
    public String boardSlug;
}

package org.example.post;

import java.util.List;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;

@Mapper
public interface PostVisibilityMapper {
    PostDetailRow findVisibleDetail(@Param("id") Long id, @Param("viewerId") Long viewerId,
            @Param("viewerRole") String viewerRole);

    int increaseViewCount(@Param("id") Long id);

    Long findBoardIdBySlug(@Param("slug") String slug);
    Long findMemberId(@Param("memberId") Long memberId);
    List<PostHeadlineRow> selectPublicByAuthorAndBoard(@Param("memberId") Long memberId,
            @Param("boardSlug") String boardSlug);

    List<PostListRow> findViewableByBoard(@Param("boardId") Long boardId, @Param("viewerId") Long viewerId,
            @Param("limit") int limit, @Param("offset") long offset);

    long countViewableByBoard(@Param("boardId") Long boardId, @Param("viewerId") Long viewerId);

    List<PostTagRow> findTagsByPostIds(@Param("postIds") List<Long> postIds);
}

package org.example.post;

import org.apache.ibatis.executor.Executor;
import org.apache.ibatis.mapping.MappedStatement;
import org.apache.ibatis.plugin.Interceptor;
import org.apache.ibatis.plugin.Intercepts;
import org.apache.ibatis.plugin.Invocation;
import org.apache.ibatis.plugin.Signature;
import org.apache.ibatis.session.ResultHandler;
import org.apache.ibatis.session.RowBounds;
import org.springframework.stereotype.Component;

// 테스트 중 Mapper가 실행한 SELECT 문장 수를 요청 스레드별로 센다.
@Component
@Intercepts(@Signature(type = Executor.class, method = "query",
        args = {MappedStatement.class, Object.class, RowBounds.class, ResultHandler.class}))
public class MyBatisStatementCounter implements Interceptor {
    private final ThreadLocal<Long> count = ThreadLocal.withInitial(() -> 0L);

    @Override
    public Object intercept(Invocation invocation) throws Throwable {
        count.set(count.get() + 1);
        return invocation.proceed();
    }

    public void clear() { count.set(0L); }
    public long getCount() { return count.get(); }
}

package org.example.post;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// JPA Statistics는 Mapper SQL을 세지 못하므로 MyBatis Executor에서 SELECT를 센다.
@SpringBootTest
@AutoConfigureMockMvc
class PostListQueryCountTest {
    @Autowired MockMvc mockMvc;
    @Autowired MyBatisStatementCounter counter;

    @Test
    void queryCountDoesNotGrowWithPageSize() throws Exception {
        counter.clear();
        mockMvc.perform(get("/api/boards/free/posts").param("size", "5"))
                .andExpect(status().isOk());
        long countForSize5 = counter.getCount();

        counter.clear();
        mockMvc.perform(get("/api/boards/free/posts").param("size", "20"))
                .andExpect(status().isOk());
        long countForSize20 = counter.getCount();

        System.out.printf("MyBatis SELECT count: size=5 %d, size=20 %d%n", countForSize5, countForSize20);
        assertTrue(countForSize5 > 0, "Mapper SELECT가 실제로 계측되어야 한다");
        assertEquals(countForSize5, countForSize20,
                "글 수가 늘어도 SELECT 문장 수가 증가하지 않아야 한다");
        assertTrue(countForSize5 <= 5, "목록·COUNT·태그 SQL이 5개 이하여야 한다");
    }
}
